\section{AGC Stage 1 Appendix}
\subsection{Stage 1A --- $\Sigma^5$ spectral survivors}
\begin{align}
\tilde\lambda(j_1,j_2,0) &= 6\bigl[j_1(j_1+1)+j_2(j_2+1)\bigr], \\
\mathcal{S}_{\mathrm{eff}} &= \bigl|\mathrm{index}(\partial D_A)\bigr|
  + \mathrm{Vol}(N^5) + \|\star\Psi-\Psi\|^2, \\
\text{survivors} &= \{({\textstyle\frac12},0,0),\,(1,0,0),\,({\textstyle\frac32},0,0)\}, \\
\tilde\lambda &\in \{4.5,\;12.0,\;22.5\}.
\end{align}

\subsection{Stage 1B --- $T^{1,1}$ $\sigma$-equilibrium}
\begin{align}
V(\sigma) &= \tfrac{3}{2}\sigma^2 + \tfrac{3}{2}\!\left(\frac{\tilde\lambda_0}{6}\right)^{\!2}\!\frac{1}{\sigma^2}
  - \tfrac{5}{3}r_0^2, \\
\sigma_* &= \sqrt{\tilde\lambda_0/6} = \sqrt{3}/2 = 0.866025403784.
\end{align}

\subsection{Stage 1C --- predictive $\Delta\eta$}
\begin{align}
\Delta\eta_k &= \frac{n_k\pi}{12}, \quad n_k = 4\,j_1(j_1+1), \\
(n_1,n_2,n_3) &= (3,8,15), \quad
\frac{n_2}{n_1}=\frac{8}{3},\;
\frac{n_3}{n_1}=5,\;
\frac{n_3}{n_2}=\frac{15}{8}.
\end{align}

